//! Device-local transaction storage for explicit soil frames.
//! Particle-order and gather scratch are regenerated by each subsequent step.

use super::*;

pub(crate) struct MpmFrameBackup {
    engine: Arc<Engine>,
    sources: Vec<wgpu::Buffer>,
    storage: wgpu::Buffer,
    armed: bool,
    reset: bool,
    dirty: Option<Vec<u32>>,
    step_epoch: Arc<()>,
    rigid_epoch: Arc<()>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mpm::replay_tests::read_words;

    #[test]
    #[ignore = "requires a real GPU adapter"]
    fn dense_frame_restores_all_streams_and_pending_materials() {
        frame_restore_fixture(false, false, false);
    }

    #[test]
    #[ignore = "requires native float-atomic GPU support"]
    fn native_frame_restores_all_streams_and_pending_materials() {
        frame_restore_fixture(true, false, false);
    }

    #[test]
    #[ignore = "requires native float-atomic GPU support"]
    fn ordered_frames_restore_material_indices_and_rebuild_scratch() {
        for (native, gather) in [(false, false), (true, false), (true, true)] {
            frame_restore_fixture(native, true, gather);
        }
    }

    fn frame_restore_fixture(native: bool, ordered: bool, gather: bool) {
        frame_restore_layout(native, ordered, gather, 0);
    }

    #[test]
    #[ignore = "requires native GPU; active/compact frame rollback including indirect dispatch"]
    fn active_frames_restore_dispatch_and_history() {
        for native in [false, true] {
            for layout in [1, 2] {
                for ordered in [false, true] {
                    frame_restore_layout(native, ordered, false, layout);
                }
            }
        }
    }

    #[test]
    #[ignore = "requires native GPU; overflow rollback and epoch/storage rejection"]
    fn active_frame_overflow_and_mutation_rejection() {
        let engine =
            Arc::new(Engine::new_gpu_with_features(wgpu::Features::SHADER_FLOAT32_ATOMIC).unwrap());
        let device = engine.device().unwrap();
        let queue = engine.queue().unwrap();
        let mut cfg = MpmConfig::sand();
        cfg.grid_size = 17;
        cfg.grid_origin = [-1.; 3];
        cfg.cell_size = 0.125;
        cfg.max_particles = 2;
        cfg.max_rigid = 1;
        let mut soil = MpmSimulation::new_native_sparse(&engine, cfg, 1).unwrap();
        soil.set_particles(queue, &[[0.; 3], [0.03; 3]]).unwrap();
        let read = |soil: &MpmSimulation| {
            buffers(soil)
                .into_iter()
                .map(|b| read_words(device, queue, b))
                .collect::<Vec<_>>()
        };
        let before = read(&soil);
        let mut backup = MpmFrameBackup::new(engine.clone(), &soil, 1_000_000).unwrap();
        backup.begin(&soil).unwrap();
        soil.step_n_with(device, queue, 0.0001, 2).unwrap();
        let status = soil.read_active_grid_status_with(device, queue).unwrap();
        assert!(status.overflow);
        assert_eq!(status.completed_substeps, 0);
        assert!(backup.rollback(&mut soil).unwrap());
        assert_eq!(read(&soil), before);
        assert!(soil.active_grid_needs_reset);
        backup.begin(&soil).unwrap();
        soil.reserve_sparse_tiles(8).unwrap();
        let grown = read(&soil);
        assert!(backup.rollback(&mut soil).is_err());
        assert_eq!(read(&soil), grown);
        drop(backup);
        let mut backup = MpmFrameBackup::new(engine.clone(), &soil, 1_000_000).unwrap();
        backup.begin(&soil).unwrap();
        soil.step_with(device, queue, 0.0001).unwrap();
        assert!(
            !soil
                .read_active_grid_status_with(device, queue)
                .unwrap()
                .faulted()
        );
        backup.commit();
        drop(backup);
        for layout in [0, 1, 2] {
            let mut soil = if layout == 2 {
                MpmSimulation::new_native_sparse(&engine, cfg, 8)
            } else {
                MpmSimulation::new_native_explicit(&engine, cfg)
            }
            .unwrap();
            if layout == 1 {
                soil.set_active_grid(true).unwrap();
            }
            soil.set_particles(queue, &[[0.; 3]]).unwrap();
            for rigid in [false, true] {
                let mut backup = MpmFrameBackup::new(engine.clone(), &soil, 1_000_000).unwrap();
                backup.begin(&soil).unwrap();
                if rigid {
                    soil.set_rigid_spheres(queue, &[([0.; 3], 0.1, [0.; 3])])
                        .unwrap();
                } else {
                    soil.set_particles(queue, &[[0.02; 3]]).unwrap();
                }
                let edited = read(&soil);
                let transfers = molla_core::gpu_metrics::TransferScope::start().unwrap();
                assert!(backup.rollback(&mut soil).is_err());
                let transfers = transfers.finish();
                assert_eq!((transfers.upload_bytes, transfers.readback_bytes), (0, 0));
                assert_eq!(read(&soil), edited);
            }
        }
        eprintln!(
            "compact overflow rollback, growth and in-frame particle/rigid edits reject without restoration; fresh growth owner succeeds"
        );
    }

    fn frame_restore_layout(native: bool, ordered: bool, gather: bool, layout: u32) {
        let engine = Arc::new(if native {
            Engine::new_gpu_with_features(wgpu::Features::SHADER_FLOAT32_ATOMIC).unwrap()
        } else {
            Engine::new_gpu().unwrap()
        });
        let device = engine.device().unwrap();
        let queue = engine.queue().unwrap();
        let mut cfg = MpmConfig::sand();
        cfg.grid_size = 8;
        cfg.grid_origin = [-0.5; 3];
        cfg.cell_size = 0.125;
        cfg.max_particles = 4;
        cfg.max_rigid = 1;
        let mut soil = if layout == 2 && native {
            MpmSimulation::new_native_sparse(&engine, cfg, 8).unwrap()
        } else if layout == 2 {
            MpmSimulation::new_sparse(&engine, cfg, 8).unwrap()
        } else if native {
            MpmSimulation::new_native_explicit(&engine, cfg).unwrap()
        } else {
            MpmSimulation::new(&engine, cfg).unwrap()
        };
        if layout == 1 {
            soil.set_active_grid(true).unwrap();
        }
        soil.set_particles(queue, &[[0.0; 3], [0.03; 3]]).unwrap();
        if ordered {
            soil.prepare_parallel_particle_tile_ordering(queue, 4)
                .unwrap();
            soil.set_particle_tile_ordering(true).unwrap();
            if gather {
                soil.prepare_deterministic_p2g().unwrap();
                soil.set_deterministic_p2g(true).unwrap();
            }
        }
        soil.particle_material_dirty = Some(vec![0, 0]);
        let read = |s: &MpmSimulation| {
            buffers(s)
                .into_iter()
                .map(|b| read_words(device, queue, b))
                .collect::<Vec<_>>()
        };
        let before = read(&soil);
        assert!(MpmFrameBackup::new(engine.clone(), &soil, 1).is_err());
        let mut backup = MpmFrameBackup::new(engine.clone(), &soil, 1_000_000).unwrap();
        let allocations = molla_core::gpu_metrics::DeviceScope::start().unwrap();
        let transfers = molla_core::gpu_metrics::TransferScope::start().unwrap();
        backup.begin(&soil).unwrap();
        assert!(backup.begin(&soil).is_err());
        soil.step_with(device, queue, 0.0001).unwrap();
        assert!(soil.particle_material_dirty.is_none());
        assert!(backup.rollback(&mut soil).unwrap());
        assert_eq!(allocations.finish().observations, 0);
        assert_eq!(transfers.finish().readback_bytes, 0);
        assert_eq!(soil.particle_material_dirty, Some(vec![0, 0]));
        assert_eq!(read(&soil), before);
        backup.begin(&soil).unwrap();
        for b in buffers(&soil) {
            queue.write_buffer(b, 0, &vec![0x55; b.size() as usize]);
        }
        assert!(backup.rollback(&mut soil).unwrap());
        assert_eq!(read(&soil), before);
        backup.begin(&soil).unwrap();
        soil.step_with(device, queue, 0.0001).unwrap();
        backup.commit();
        assert!(!backup.rollback(&mut soil).unwrap());
        assert_ne!(read(&soil), before);
        if layout > 0 {
            let committed = read(&soil);
            let dispatch = read_words(device, queue, &soil.active_tiles.indirect);
            assert!(dispatch[0] > 0 && dispatch[1] > 0);
            backup.begin(&soil).unwrap();
            soil.step_n_with(device, queue, 0.0001, 3).unwrap();
            assert!(backup.rollback(&mut soil).unwrap());
            assert_eq!(read(&soil), committed);
            assert_eq!(
                read_words(device, queue, &soil.active_tiles.indirect),
                dispatch
            );
            soil.step_with(device, queue, 0.0001).unwrap();
            let status = soil.read_active_grid_status_with(device, queue).unwrap();
            assert!(!status.faulted());
            assert_eq!(status.completed_substeps, 2);
        }
        soil.use_active_grid = !soil.use_active_grid;
        assert!(backup.begin(&soil).is_err());
        println!(
            "layout={layout} native={native} ordered={ordered} gather={gather}: frame streams including material index tail and active dispatch restored bit-exactly; pending materials restored; retained copies allocate/map zero buffers"
        );
    }
}

fn invalid(message: &str) -> Error {
    Error::Solver(format!("MPM frame backup: {message}"))
}

fn buffers(soil: &MpmSimulation) -> Vec<&wgpu::Buffer> {
    soil.checkpoint_buffers()
        .into_iter()
        .chain([
            &soil.g_mass,
            &soil.g_momentum,
            &soil.g_velocity,
            &soil.g_rigid_mask,
            &soil.g_kdiag,
            &soil.g_velocity_prev,
            &soil.rigid_center,
            &soil.rigid_vel,
            &soil.rigid_wrench,
        ])
        .chain(soil.use_active_grid.then_some(&soil.active_tiles.indirect))
        .collect()
}

impl MpmFrameBackup {
    pub(crate) fn new(engine: Arc<Engine>, soil: &MpmSimulation, max_bytes: u64) -> Result<Self> {
        engine.check_device()?;
        let device = engine.device().ok_or_else(|| invalid("GPU required"))?;
        crate::kernels::validate_soil_device(device, &soil.device)?;
        Self::validate_mode(soil)?;
        let sources: Vec<_> = buffers(soil).into_iter().cloned().collect();
        let bytes = sources
            .iter()
            .try_fold(0u64, |sum, b| sum.checked_add(b.size()))
            .ok_or_else(|| invalid("capacity overflow"))?;
        if bytes > max_bytes || bytes > device.limits().max_buffer_size {
            return Err(invalid("backup exceeds budget or device capacity"));
        }
        let storage = molla_core::gpu_create_buffer!(
            device,
            &wgpu::BufferDescriptor {
                label: Some("MPM frame transaction"),
                size: bytes,
                usage: wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            }
        );
        Ok(Self {
            engine,
            sources,
            storage,
            armed: false,
            reset: false,
            dirty: None,
            step_epoch: soil.step_epoch.clone(),
            rigid_epoch: soil.rigid_epoch.clone(),
        })
    }

    fn validate_mode(soil: &MpmSimulation) -> Result<()> {
        if !matches!(soil.cfg.time_step, MpmTimeStep::Explicit) {
            return Err(invalid("requires explicit soil"));
        }
        if soil.use_particle_order
            && soil
                .particle_order
                .as_ref()
                .is_none_or(|order| order.capacity < soil.particle_count)
        {
            return Err(invalid("particle count exceeds prepared ordering capacity"));
        }
        Ok(())
    }

    pub(crate) fn bytes(&self) -> u64 {
        self.storage.size()
    }

    fn same_storage(&self, soil: &MpmSimulation) -> bool {
        let current = buffers(soil);
        current.len() == self.sources.len()
            && current.iter().zip(&self.sources).all(|(a, b)| *a == b)
    }

    pub(crate) fn begin(&mut self, soil: &MpmSimulation) -> Result<()> {
        self.engine.check_device()?;
        Self::validate_mode(soil)?;
        if self.armed || !self.same_storage(soil) {
            return Err(invalid("frame pending or soil storage replaced"));
        }
        self.reset = soil.active_grid_needs_reset;
        self.dirty = soil.particle_material_dirty.clone();
        self.step_epoch = soil.step_epoch.clone();
        self.rigid_epoch = soil.rigid_epoch.clone();
        self.copy(false);
        self.armed = true;
        Ok(())
    }

    fn copy(&self, restore: bool) {
        let mut encoder = self
            .engine
            .device()
            .unwrap()
            .create_command_encoder(&Default::default());
        let mut offset = 0;
        for source in &self.sources {
            if restore {
                encoder.copy_buffer_to_buffer(&self.storage, offset, source, 0, source.size());
            } else {
                encoder.copy_buffer_to_buffer(source, 0, &self.storage, offset, source.size());
            }
            offset += source.size();
        }
        self.engine.queue().unwrap().submit([encoder.finish()]);
    }

    pub(crate) fn rollback(&mut self, soil: &mut MpmSimulation) -> Result<bool> {
        self.engine.check_device()?;
        if !self.armed {
            return Ok(false);
        }
        Self::validate_mode(soil)?;
        if !self.same_storage(soil)
            || !Arc::ptr_eq(&self.step_epoch, &soil.step_epoch)
            || !Arc::ptr_eq(&self.rigid_epoch, &soil.rigid_epoch)
        {
            return Err(invalid(
                "soil storage or configuration changed during frame",
            ));
        }
        self.copy(true);
        soil.active_grid_needs_reset = self.reset;
        soil.particle_material_dirty = self.dirty.take();
        self.armed = false;
        Ok(true)
    }

    pub(crate) fn commit(&mut self) {
        self.armed = false;
        self.dirty = None;
    }
}
